from sympy import sqrt, I, S
from sympy.simplify.sqrtdenest import sqrt_biquadratic_denest, _sqrt_symbolic_denest

expr = sqrt(2 + I)
a = 2 + I
b = S.Zero
r = S.One
d2 = (a**2 - b**2*r)
print('d2:', d2, type(d2))
try:
    print('r <= 0:', r <= 0)
except Exception as e:
    print('r <= 0 raised', type(e), e)
try:
    print('d2 < 0:', d2 < 0)
except Exception as e:
    print('d2 < 0 raised', type(e), e)
try:
    print('symbolic:', _sqrt_symbolic_denest(a,b,r))
except Exception as e:
    print('symbolic raised', type(e), e)
try:
    print('biquadratic:', sqrt_biquadratic_denest(expr,a,b,r,d2))
except Exception as e:
    print('biquadratic raised', type(e), e)
